Actionscript.script:
起跳速度 = -3;

停止机率 = 500;
随机移动机率 = 500;

攻击欲望 = 3;
x轴攻击范围 = 100;
y轴攻击范围 = 30;
x轴保持距离 = 100;

近战技能库 = [];
中程技能库 = [];
远程技能库 = [];
超远程技能库 = [];
横向技能库 = [];
高空技能库 = [];
范围外技能库 = [];
身后技能库 = [];
残血技能库 = [];
斩杀技能库 = [];
受击技能库 = [];

近战技能库.push("撕裂嘶吼");
中程技能库.push("跳跃撕咬");
远程技能库.push("跑动捕杀");

近战技能随机数 = 近战技能库.length;
中程技能随机数 = 中程技能库.length;
远程技能随机数 = 远程技能库.length;
超远程技能随机数 = 超远程技能库.length;
横向技能随机数 = 横向技能库.length;
高空技能随机数 = 高空技能库.length;
范围外技能随机数 = 范围外技能库.length;
身后技能随机数 = 身后技能库.length;
残血技能随机数 = 残血技能库.length;
斩杀技能随机数 = 斩杀技能库.length;
受击技能随机数 = 受击技能库.length;



男_攻击呐喊_库 = [];
男_中招呐喊_库 = [];
男_击倒呐喊_库 = [];



初始化敌人模板 = _root.初始化敌人模板;
初始化敌人模板();

克隆兽完全体 = false;
// γ-ECHO 私有决策：不改共享 AI、攻击帧、子弹威力或段数。
// baseline 保留诺亚原始索敌脚本，供同面板斗兽对照。
// 65 级起原普通攻击获得刚体；高等级镜像未证明私有策略有收益。
// 显式模式只供隔离对照，正常生成按等级选择已验证的默认分支。
if (克隆兽AI模式 != "baseline" && 克隆兽AI模式 != "enhanced") {
    克隆兽AI模式 = 等级 >= 65 ? "baseline" : "enhanced";
}
// 暴君型摄食续航沿用子弹继承与 LifeStealDamageHandle 的统一结算。
// 普通生成不接受诊断开关；λ 型始终不获得此项固有吸血。
吸血 = 克隆兽完全体 ? 5 : 0;
if (_arenaCalibrationUnit === true && 克隆兽吸血模式 == "off") 吸血 = 0;
gammaEchoDecisionCount = 0;
gammaEchoSkillCount = 0;
gammaEchoAlignCount = 0;

gammaEchoChooseSkill = function(distanceX:Number, distanceZ:Number, targetHeight:Number):String {
    if (isNaN(distanceX) || isNaN(distanceZ) || isNaN(targetHeight)) return "none";
    if (distanceX < 0 || distanceZ < 0 || distanceZ > 24 || targetHeight > 65) return "none";
    if (distanceX <= 150) return "撕裂嘶吼";
    if (distanceX <= 230) return "跳跃撕咬";
    if (distanceX <= 430) return "跑动捕杀";
    return "none";
};

gammaEchoThink = function(sensor:MovieClip):Void {
    var actor:MovieClip = this;
    if (_root.暂停 || !(actor.hp > 0) || actor.倒地 || actor.浮空 || actor.硬直中) return;
    if (_root.控制目标 == actor._name && _root.控制目标全自动 == false) return;
    if (actor.状态 != "空手站立" && actor.状态 != "空手行走" && actor.状态 != "空手跑") return;
    var target:MovieClip = _root.gameworld[actor.攻击目标];
    if (!(target.hp > 0) || target == actor || target.area == null) return;
    var dx:Number = target._x - actor._x;
    var dz:Number = target.Z轴坐标 - actor.Z轴坐标;
    var height:Number = target.Z轴坐标 - target._y;
    if (isNaN(dx) || isNaN(dz) || isNaN(height)) return;
    actor.gammaEchoDecisionCount++;
    // 与现有行走函数共享方向标志，每帧仍只有原生控制块执行一次碰撞移动。
    if (Math.abs(dz) > 24 || Math.abs(dx) > 430 || !sensor.hitTest(target.area)) {
        actor.上行 = dz < -6;
        actor.下行 = dz > 6;
        actor.左行 = dx < -70;
        actor.右行 = dx > 70;
        actor.gammaEchoAlignCount++;
        if (Math.abs(dx) > 230 && actor.状态 != "空手跑") actor.状态改变("空手跑");
        return;
    }
    var move:String = actor.gammaEchoChooseSkill(Math.abs(dx), Math.abs(dz), height);
    if (move == "none") return;
    actor.左行 = false;
    actor.右行 = false;
    actor.上行 = false;
    actor.下行 = false;
    if (dx < 0) actor.方向改变("左");
    else if (dx > 0) actor.方向改变("右");
    // 出招间隔由原动作完整时间轴约束，不在收招后叠加私有空等。
    actor.gammaEchoSkillCount++;
    actor.gammaEchoLastMove = move;
    actor.近战招式 = move;
    actor.状态改变("近战");
};

if (克隆兽AI模式 == "enhanced") {
    // 私有控制器独占自动出招，避免通用近身普攻抢占具有原生刚体的近战主招。
    x轴攻击范围 = 0;
    y轴攻击范围 = 24;
    x轴保持距离 = 100;
    if (unitAI.data != null) {
        unitAI.data.xrange = 0;
        unitAI.data.zrange = 24;
        unitAI.data.xdistance = 100;
    }
}
// 仅在隔离标定单位上保留私有配置；不占用 ArenaSkillCache 的严格结果字段。
if (_arenaCalibrationUnit === true) {
    gammaEchoArenaAudit = {
        kind:"GammaEchoAI",
        revision:5,
        mode:克隆兽AI模式,
        fullPower:克隆兽完全体,
        lifeStealPercent:吸血,
        attackRange:x轴攻击范围,
        laneRange:y轴攻击范围,
        keepDistance:x轴保持距离,
        hpMin:hp_min,
        hpMax:hp_max,
        baseAttack:空手攻击力,
        damageMultiplier:1
    };
}

onClipEvent (enterFrame) {
if (_parent.克隆兽AI模式 == "enhanced") {
_parent.gammaEchoThink(this);
} else {

    if (this._currentframe == 1 and _root.gameworld[_parent.攻击目标].hp > 0)
    {
        距离X = Math.abs(_parent._x - _root.gameworld[_parent.攻击目标]._x);
        距离Z = Math.abs(_parent.Z轴坐标 - _root.gameworld[_parent.攻击目标].Z轴坐标);
        距离Y = 距离Z;
        //有高空招式时激活下列内容
        //敌方高度 = _root.gameworld[_parent.攻击目标].Z轴坐标 - _root.gameworld[_parent.攻击目标]._y;
        if (this.hitTest(_root.gameworld[_parent.攻击目标].area) and 距离Z <= _parent.y轴攻击范围)
        {
            play();
            if (random(_parent.攻击欲望) == 0)
            {
                /*有残血技能时激活下方内容，注意调整触发的距离X的范围
                if(_parent.hp <  _parent.hp满血值*0.3 && 距离X >= 0 && 距离X < 500  && _parent.残血技能随机数 > 0)
                {
                    _parent.近战招式 =  _parent.残血技能库[random(_parent.残血技能随机数)];
                    _parent.状态改变("近战");
                }else
                */
                /*有斩杀技能时激活下方内容，注意调整触发的距离X的范围
                if(_root.gameworld[_parent.攻击目标].hp <  _root.gameworld[_parent.攻击目标].hp满血值*0.3  && 距离X < 600 && _parent.残血技能随机数 > 0)
                {
                    _parent.近战招式 =   _parent.斩杀技能库[random(_parent.斩杀技能随机数)];
                    _parent.状态改变("近战");
                }else
                */
                if (_parent._x > _root.gameworld[_parent.攻击目标]._x)
                {
                    _parent.方向改变("左");
                }
                else if (_parent._x < _root.gameworld[_parent.攻击目标]._x)
                {
                    _parent.方向改变("右");
                }

                if (距离X < 150)
                {
                    if (_parent.近战技能随机数 > 0)
                    {
                        _parent.近战招式 = _parent.近战技能库[random(_parent.近战技能随机数)];
                        _parent.状态改变("近战");
                    }else{
                        _parent.状态改变("空手攻击");
                    }
                }
                else if (距离X < 230 and _parent.中程技能随机数 > 0)
                {

                    _parent.近战招式 = _parent.中程技能库[random(_parent.中程技能随机数)];
                    _parent.状态改变("近战");
                }
                else if (_parent.远程技能随机数 > 0 and 距离X < 500 )
                {
                    _parent.近战招式 = _parent.远程技能库[random(_parent.远程技能随机数)];
                    _parent.状态改变("近战");
                }
                else if (_parent.超远程技能随机数 > 0 and 距离X >= 500 )
                {
                    _parent.近战招式 = _parent.超远程技能库[random(_parent.超远程技能随机数)];
                    _parent.状态改变("近战");
                }
            }

        }
        /*有高空招式时激活下方内容
        else if (敌方高度 > 80 and _parent.高空技能随机数 > 0 and 距离Z <= _parent.y轴攻击范围 * 5)
        {

            if (random(_parent.攻击欲望) == 0)
            {
                if (_parent._x > _root.gameworld[_parent.攻击目标]._x)
                {
                    _parent.方向改变("左");
                }
                else if (_parent._x < _root.gameworld[_parent.攻击目标]._x)
                {
                    _parent.方向改变("右");
                }
                //可以调整触发的距离X
                if (距离X < 200 && 距离Z <= _parent.y轴攻击范围)
                {
                    _parent.高空招式 = _parent.高空技能库[random(_parent.高空技能随机数)];
                    if (敌方高度 > 200 and _parent.等级 >= 50 and _parent.高空招式 == "中空连招")
                    {
                        _parent.高空招式 = "高空连招";
                    }
                    _parent.状态改变("空手跳");
                }
            }
        }
        */
        /*有身后招式时激活下列内容
        else if (距离X < 130 and 距离Z <= _parent.y轴攻击范围)
        {
            if (_parent.身后技能随机数 > 0 and random(_parent.攻击欲望) == 0)
            {
                _parent.近战招式 = _parent.身后技能库[random(_parent.身后技能随机数)];
                _parent.状态改变("近战");
            }
        }
        */
        /*有横向招式时激活下列内容
        else if (距离X < 220 and _parent.横向技能随机数 > 0 and 距离Z <= 90 and random(_parent.攻击欲望 * 2) == 0)
        {

            if (_parent._x > _root.gameworld[_parent.攻击目标]._x)
            {
                _parent.方向改变("左");
            }
            else if (_parent._x < _root.gameworld[_parent.攻击目标]._x)
            {
                _parent.方向改变("右");
            }
            _parent.近战招式 = _parent.横向技能库[random(_parent.横向技能随机数)];
            _parent.状态改变("近战");
        }
        */
        /*有范围外招式时激活下列内容
        else
        {
            if (_parent.范围外技能随机数 > 0 and random(_parent.攻击欲望 * 15) == 0)
            {
                if (_parent._x > _root.gameworld[_parent.攻击目标]._x)
                {
                    _parent.方向改变("左");
                }
                else if (_parent._x < _root.gameworld[_parent.攻击目标]._x)
                {
                    _parent.方向改变("右");
                }
                _parent.近战招式 = _parent.范围外技能库[random(_parent.范围外技能随机数)];
                _parent.状态改变("近战");
            }
        }
        */

    }

}
}

onClipEvent (load) {
    _parent.刚体 = true;
}
onClipEvent (unload) {
    _parent.刚体 = false;
}

onClipEvent(load){
    if(_parent.等级>=65){
        _parent.刚体 = true;
    }
   _parent.背枪 = true;
}
onClipEvent(unload){
   _parent.刚体 = false;
   _parent.背枪 = false;
}

onClipEvent(load){
   gotoAndPlay(random(15));
   躲闪 = true;
}
onClipEvent(unload){
   躲闪 = false;
}

onClipEvent (load) {
    if (!_root.是否阴影)
    {
        this._visible = false;
    }
}
